tmp=$(mktemp -d); export PMW_HOME="$tmp/home" PMW_PROJECT_SLUG=baseline-gate; root="$PMW_HOME/projects/$PMW_PROJECT_SLUG"; mkdir -p "$root/runs"; printf '{"current_run_id":"r1","latest_run_id":"r1"}
' > "$root/project.json"; printf '{"dimension":"product_role","source":"用户","summary":"已有功能负责承接门店服务转化","confidence":"confirmed","run_id":"r1"}
{"dimension":"target_trigger","source":"用户","summary":"购车用户在车型决策后进入当前链路","confidence":"confirmed","run_id":"r1"}
{"dimension":"current_alternative","source":"用户","summary":"用户会去汽车之家其他页面或竞品平台查看门店信息","confidence":"confirmed","run_id":"r1"}
{"dimension":"pain_loss","source":"用户","summary":"主要损失是时间成本和决策困难","confidence":"confirmed","run_id":"r1"}
{"dimension":"goal_countermetric","source":"用户","summary":"主目标提升电话 IM 联系销售转化，反指标是不牺牲信息可信度","confidence":"confirmed","run_id":"r1"}
' > "$root/discovery.jsonl"; printf '{"event":"decision","status":"已确认","title":"D1 首屏策略","summary":"选择快速联系优先"}
{"event":"decision","status":"已确认","title":"D2 报价边界","summary":"选择补后 xx 万元起，不承诺最终成交价"}
' > "$root/runs/r1.jsonl"; brief="$tmp/aligned.md"; printf '产品简报：经销商门店服务转化优化
确认状态：已对齐

一句话判断：这是已有功能优化，当前链路会跳到其他页面或竞品平台，但缺线上截图 / 视觉基线。
' > "$brief"; bin/pmw-discovery-gate check --target brief --brief "$brief" --json; code=$?; rm -rf "$tmp"; exit $code

